func DispatchHaskell(d, p, m byte, vec *HaskellStateVector) error {
	identity, err := ResolveHaskellIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := HaskellTable[identity.Code]
	if handler == nil {
		return errors.New("haskell kernel not initialized")
	}
	return handler(identity, vec)
}

func GetHaskellExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&HaskellMetrics[code])
}
